import ast
import os
import sys
import subprocess
import tempfile
import shutil
import tomllib
import re
import time
import json
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency on artifacts module (assumed available in environment or parallel)
try:
    from hae.evaluation.artifacts import (
        filter_bundle, 
        partition_bundle, 
        count_source_files,
        is_generated_path,
        is_malformed_path
    )
except ImportError:
    # Fallback minimal implementation if artifacts.py is not yet available in path
    # This ensures harness.py can be tested in isolation if needed, 
    # though the spec implies it's a dependency.
    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return bundle
    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        return bundle, {}, {}
    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        return sum(1 for p in bundle if p.endswith(suffixes))
    def is_generated_path(path: str) -> bool:
        return False
    def is_malformed_path(path: str) -> bool:
        return False

@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED

@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name}: {g.status.upper()} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }

def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Matches: ```python\n...``` or ```path/to/file.py\n...```
    # We look for blocks where the info string might contain a path ending in .py
    pattern = r"```(?:python|py)?\s*(.*?)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for i, (info, content) in enumerate(matches):
        # Try to extract a filename from the info string
        # Common patterns: "path/to/file.py", "file.py", "python path/to/file.py"
        filename = None
        parts = info.strip().split()
        for part in parts:
            if part.endswith('.py'):
                filename = part
                break

        if not filename:
            # If no explicit filename, generate a placeholder based on index
            # But the spec implies we recover a path->content map. 
            # If we can't determine path, we might skip or use a generic name.
            # However, for the harness to work, we need valid paths.
            # Let's assume if no path is found, we can't reliably map it.
            # But often agents write ```python\n...``` without path.
            # In that case, we can't know the path. 
            # The spec says "Recovers a path->content map". 
            # If we can't recover a path, we can't put it in the map.
            continue

        # Clean up filename (remove leading slashes etc if any)
        filename = filename.lstrip('/')
        if filename:
            bundle[filename] = content

    return bundle

class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int=DEFAULT_TIMEOUT_S, penalty_per_gate: float=DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str]=None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any=None, deliverable_text: str='') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object if it exists
        if workspace is not None:
            # Assuming workspace has a method to get files or is a dict-like
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            elif hasattr(workspace, 'files'):
                bundle = workspace.files

        # If bundle is empty, try extracting from deliverable text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str='bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        if authored_files == 0:
            return self._create_empty_report(source)

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run verification on the directory
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]]=None, source: str='directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for authored files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out generated dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.join(root, d))]
                for file in files:
                    full_path = os.path.join(root, file)
                    rel_path = os.path.relpath(full_path, workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        if authored_files == 0:
            return self._create_empty_report(source)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No files found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No files found'),
            GateResult(name='tests', status=FAILED, method='pytest_run', detail='No files found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No files found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files to parse',
                duration_s=time.time() - start
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='Syntax errors found: ' + '; '.join(errors),
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata (pyproject.toml, setup.py, setup.cfg) found',
                duration_s=time.time() - start
            )

        # If pyproject.toml is present, validate it
        if found_metadata == 'pyproject.toml':
            content = authored['pyproject.toml']
            try:
                data = tomllib.loads(content)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib_validation',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib_validation',
                    detail=f'pyproject.toml is malformed: {e}',
                    duration_s=time.time() - start
                )

        # Try to install if pip is available
        # We run pip install -e . --no-deps --no-build-isolation
        try:
            # Check if pip is available
            subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                capture_output=True,
                timeout=10
            )

            # Run install
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start

            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                # If install fails, it might be due to missing deps or other issues.
                # The spec says "must exist and be valid/installable".
                # If pip is available and install fails, it's FAILED.
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )

        except FileNotFoundError:
            # pip not available
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available',
                duration_s=time.time() - start
            )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'Error during build check: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Identify non-test authored modules
        # Test files usually have 'test' in name or are in tests/ dir
        # We look for .py files that are not test files
        modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Also skip __init__.py? Usually importing package works if __init__ is there.
            # But importing __init__.py directly might be trivial.
            # Let's include all non-test .py files.
            modules.append(path)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # We need to import each module in a subprocess to isolate failures
        # But doing one by one is slow. Let's try to import them all in one script?
        # No, if one fails, we need to know which one.
        # Let's iterate.

        import_errors = []
        module_not_found_errors = []

        for mod_path in modules:
            # Convert path to module name
            # e.g. src/foo/bar.py -> foo.bar
            # e.g. foo/bar.py -> foo.bar
            rel_path = mod_path
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]

            if rel_path.endswith('.py'):
                rel_path = rel_path[:-3]

            module_name = rel_path.replace('/', '.').replace('\\', '.')

            # Skip if it's just __init__
            if module_name.endswith('.__init__'):
                module_name = module_name[:-9]
                if not module_name:
                    continue

            # Run import check
            code = f"import {module_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped?
                        # Spec: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                        # This implies if the module itself imports fine but a dep fails, it's skipped.
                        # But if the module itself is not found, it's failed.
                        # How to distinguish?
                        # If the error is "No module named 'foo'" and foo is the module we tried to import, it's failed.
                        # If the error is "No module named 'opentelemetry'" inside foo, it's skipped.

                        # Simple heuristic: if the module name we tried to import is in the error, it's failed.
                        if module_name in stderr or f"'{module_name}'" in stderr:
                            import_errors.append(f"{module_name}: {stderr.strip()}")
                        else:
                            module_not_found_errors.append(f"{module_name}: {stderr.strip()}")
                    else:
                        import_errors.append(f"{module_name}: {stderr.strip()}")

            except subprocess.TimeoutExpired:
                import_errors.append(f"{module_name}: Timeout")
            except Exception as e:
                import_errors.append(f"{module_name}: {e}")

        duration = time.time() - start

        if import_errors:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='Import errors: ' + '; '.join(import_errors),
                duration_s=duration,
                evidence={'errors': import_errors}
            )

        if module_not_found_errors:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail='Skipped due to missing third-party dependencies: ' + '; '.join(module_not_found_errors),
                duration_s=duration,
                evidence={'skipped': module_not_found_errors}
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail=f"All {len(modules)} modules imported successfully",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest_run',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Check if pytest is installed
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pytest', '--version'],
                capture_output=True,
                timeout=10
            )
            use_pytest = True
        except Exception:
            use_pytest = False

        if use_pytest:
            # Run pytest
            # We run pytest on the test files
            # Note: pytest might fail if imports fail.
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'] + test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                duration = time.time() - start

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest_run',
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # If tests couldn't even run due to missing deps, skip?
                        # Spec: "If 0 tests are collected because of ModuleNotFoundError... return SKIPPED"
                        # If tests ran but failed, it's FAILED.
                        # If collection failed, it's SKIPPED.
                        # Pytest exit code 2 is usually collection error.
                        if result.returncode == 2:
                            return GateResult(
                                name='tests',
                                status=SKIPPED,
                                method='pytest_run',
                                detail='Tests skipped due to missing dependencies',
                                duration_s=duration,
                                evidence={'stderr': result.stderr}
                            )

                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest_run',
                        detail='Tests failed',
                        duration_s=duration,
                        evidence={'stdout': result.stdout, 'stderr': result.stderr}
                    )

            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest_run',
                    detail='Tests timed out',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest_run',
                    detail=f'Error running tests: {e}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Run a script that imports each test file and collects/executes tests
            # This is complex to do in one go. Let's write a temporary runner script.

            runner_code = '''
import sys
import os
import unittest
import importlib.util

def run_tests(test_files):
    collected = 0
    failed = 0
    errors = []

    for tf in test_files:
        try:
            # Ensure the directory containing the test file is in sys.path
            test_dir = os.path.dirname(os.path.abspath(tf))
            if test_dir not in sys.path:
                sys.path.insert(0, test_dir)

            # Load module with unique name to avoid collisions
            mod_name = os.path.splitext(os.path.basename(tf))[0]
            spec = importlib.util.spec_from_file_location(mod_name, tf)
            module = importlib.util.module_from_spec(spec)
            sys.modules[mod_name] = module
            spec.loader.exec_module(module)

            # Collect bare test functions
            for name in dir(module):
                if name.startswith('test_'):
                    func = getattr(module, name)
                    if callable(func) and func.__code__.co_argcount == 0:
                        collected += 1
                        try:
                            func()
                        except Exception as e:
                            failed += 1
                            errors.append(f"{tf}:{name}: {e}")

            # Collect unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj is not unittest.TestCase:
                    suite = unittest.TestLoader().loadTestsFromTestCase(obj)
                    collected += suite.countTestCases()
                    result = unittest.TextTestRunner(verbosity=0).run(suite)
                    if not result.wasSuccessful():
                        failed += len(result.failures) + len(result.errors)
                        for test, err in result.failures + result.errors:
                            errors.append(f"{tf}:{test}: {err}")

        except ModuleNotFoundError as e:
            # If module not found, it's a skip condition for the whole gate if all fail this way?
            # Spec: "If 0 tests are collected because of ModuleNotFoundError... return SKIPPED"
            # We'll track this.
            errors.append(f"ModuleNotFoundError: {e}")
        except Exception as e:
            errors.append(f"ImportError: {e}")

    if collected == 0 and errors:
        # Check if all errors are ModuleNotFoundError
